import pyomo.environ as pyo

DATA = {
    "FOODS": ["almonds", "cashews"],
    "calories": {"almonds": 200, "cashews": 300},
    "protein": {"almonds": 20, "cashews": 25},
    "fat": {"almonds": 15, "cashews": 12},
    "min_calories": 10000,
    "min_protein": 800,
    "almond_to_cashew_ratio": 2,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["FOODS"])

    model.servings = pyo.Var(
        model.FOODS,
        domain=pyo.NonNegativeReals,
    )

    def calories_rule(m):
        return sum(d["calories"][f] * m.servings[f] for f in m.FOODS) >= d["min_calories"]

    model.calories_constraint = pyo.Constraint(rule=calories_rule)

    def protein_rule(m):
        return sum(d["protein"][f] * m.servings[f] for f in m.FOODS) >= d["min_protein"]

    model.protein_constraint = pyo.Constraint(rule=protein_rule)

    def ratio_rule(m):
        return (
            m.servings["almonds"]
            - d["almond_to_cashew_ratio"] * m.servings["cashews"]
            >= 0
        )

    model.ratio_constraint = pyo.Constraint(rule=ratio_rule)

    def obj_rule(m):
        return sum(d["fat"][f] * m.servings[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    return model


